	c->backoff_ms = c->backoff_ms * 2 > BACKOFF_MAX_MS ? BACKOFF_MAX_MS : c->backoff_ms * 2;
	return -1;
}

int ipc_send(struct ipc_conn *c, const void *buf, size_t len, int64_t now_ns)
{
	ssize_t n;

	if (len == 0 || len > MSG_MAX) {
		errno = EINVAL;
		goto drop;
