	CHECK(pid >= 0);
	if (pid == 0) {
		struct ipc_conn c;

		if (ipc_conn_init(&c, "t3") < 0)
			_exit(2);
		fill_alert(&m, 7);
		if (ipc_send(&c, &m, sizeof(m), 0) < 0)
