	CHECK(kill(pid, SIGKILL) == 0);
	CHECK(waitpid(pid, &status, 0) == pid && WIFSIGNALED(status));
	CHECK(ipc_recv(afd, buf, sizeof(buf), &rej) == 0);
	CHECK(close(afd) == 0 && close(lfd) == 0);
}

