		}
		log_msg(LOG_E, "accept_failed err=%s", strerror(errno));
		return -1;
	}
	for (i = 0; i < MAX_CLIENTS; i++) {
		if (hub->cl[i].fd < 0) {
			hub->cl[i].fd = fd;
			hub->cl[i].sensor = -1;
			return 0;
		}
	}
