#include "check.h"
#include "msg.h"
#include "record.h"
#include "seglog.h"

#include <fcntl.h>
#include <sys/stat.h>
#include <unistd.h>

#define MS 1000000LL
#define MAX_RECS 4096

static char base[] = "/tmp/dlby-seglog-XXXXXX";

/* Everything readable across a directory's segments. */
struct scan {
	size_t   n;
	uint8_t  type[MAX_RECS];
	uint32_t seq[MAX_RECS];
	uint32_t last_gap_truncated;
	uint64_t bad;
	bool     contiguous;
};

static int scan_cb(void *ctx, const struct rec *r, const uint8_t *payload)
{
	struct scan *s = ctx;

	CHECK(s->n < MAX_RECS);
	if (s->n && r->seq != s->seq[s->n - 1] + 1)
		s->contiguous = false;
	s->type[s->n] = r->type;
	s->seq[s->n] = r->seq;
	s->n++;
	if (r->type == REC_GAP)
		s->last_gap_truncated = get_le32(payload);
	return 0;
}

static void scan_dir(const char *dir, struct scan *s)
{
	char path[256], name[32];
	uint32_t *v;
	off_t good, end;
	size_t n, i;
	int fd;

	memset(s, 0, sizeof(*s));
	s->contiguous = true;
	CHECK(seg_list(dir, &v, &n) == 0);
	for (i = 0; i < n; i++) {
		seg_name(name, sizeof(name), v[i]);
		snprintf(path, sizeof(path), "%s/%s", dir, name);
		fd = open(path, O_RDONLY | O_CLOEXEC);
		CHECK(fd >= 0);
		CHECK(rec_scan(fd, scan_cb, s, &good, &end) == 0);
		s->bad += (uint64_t)(end - good);
		CHECK(close(fd) == 0);
	}
