	run_stream("stream", 0);
	CHECK(nsync == 6);			/* GAP + 5 timed */
	CHECK(sync_at[0] == 0);
	for (i = 1; i < nsync; i++) {
		CHECK(sync_at[i] - sync_at[i - 1] >= 1000 * MS);
		CHECK(sync_at[i] - sync_at[i - 1] <= 1100 * MS);
	}
}

static void test_state_sync_restarts_window(void)
