static int scan_cb(void *ctx, const struct rec *r, const uint8_t *payload)
{
	struct scan *s = ctx;

	CHECK(s->n < MAX_RECS);
	if (s->n && r->seq != s->seq[s->n - 1] + 1)
		s->contiguous = false;
	s->type[s->n] = r->type;
	s->seq[s->n] = r->seq;
	s->n++;
	if (r->type == REC_GAP)
		s->last_gap_truncated = get_le32(payload);
	return 0;
}

