	memset(s, 0, sizeof(*s));
	s->contiguous = true;
	CHECK(seg_list(dir, &v, &n) == 0);
	for (i = 0; i < n; i++) {
		seg_name(name, sizeof(name), v[i]);
		snprintf(path, sizeof(path), "%s/%s", dir, name);
		fd = open(path, O_RDONLY | O_CLOEXEC);
		CHECK(fd >= 0);
		CHECK(rec_scan(fd, scan_cb, s, &good, &end) == 0);
