	RUN(test_steady_stream_syncs_each_second);
	RUN(test_state_sync_restarts_window);
	RUN(test_idle_clean_never_syncs);

	for (i = 0; i < sizeof(dirs) / sizeof(dirs[0]); i++) {
		snprintf(dir, sizeof(dir), "%s/%s", base, dirs[i]);
		rm_tree(dir);
	}
	CHECK(rmdir(base) == 0);
	return 0;
}

