static void append_sonar(struct seglog *sl, uint32_t seq, int64_t now)
{
	struct sonar_msg m;

	memset(&m, 0, sizeof(m));
	m.type = MSG_SONAR;
	m.seq = seq;
	m.origin_ns = (uint64_t)now;
	CHECK(seglog_append(sl, MSG_SONAR, &m, sizeof(m), now) == 0);
}

