{
	struct alert_msg m;

	memset(&m, 0, sizeof(m));
	m.type = MSG_ALERT;
	m.state = ST_CLEAR;
	m.origin_ns = (uint64_t)now;
	return seglog_append(sl, MSG_ALERT, &m, sizeof(m), now);
}

