/* Child side of dlby-super's heartbeat (DESIGN.md §2 E).
 *
 * dlby-super passes one end of a SOCK_SEQPACKET socketpair as $DLBY_HB_FD. A
 * child sends a struct hb_msg every HB_PERIOD_NS from its main event loop, never
 * a side thread, so a stuck loop goes quiet. EOF on the fd means super is gone:
 * the child exits. hb_init also sets PR_SET_PDEATHSIG(SIGTERM).
 *
 * Without $DLBY_HB_FD the child runs standalone (bench, tests): hb_tick and
 * hb_readable do nothing and hb_due_ns is INT64_MAX.
 */
#ifndef DLBY_HB_H
#define DLBY_HB_H

#include <stdint.h>

#define HB_FD_ENV        "DLBY_HB_FD"
#define HB_SUPER_PID_ENV "DLBY_SUPER_PID"
#define HB_PERIOD_NS     1000000000LL

struct hb {
	int      fd;		/* -1 when standalone; poll it for POLLIN/POLLHUP */
	uint32_t seq;
	int64_t  next_ns;
};

/* Returns 1 if supervised, 0 if standalone, -1 with errno on error (ESRCH:
 * super already died before PDEATHSIG was armed). */
int hb_init(struct hb *hb);

/* Send a heartbeat if one is due. Returns 0, or -1 if super is gone. */
int hb_tick(struct hb *hb, int64_t now_ns);

/* Call when hb->fd is readable. Returns 0, or -1 on EOF (super is gone). */
int hb_readable(struct hb *hb);

int64_t hb_due_ns(const struct hb *hb);

#endif

#include "hb.h"
#include "msg.h"

#include <errno.h>
#include <fcntl.h>
#include <signal.h>
#include <stdlib.h>
#include <string.h>
#include <sys/prctl.h>
#include <sys/socket.h>
#include <unistd.h>

static int parse_long(const char *s, long lo, long hi, long *out)
{
	char *end;
	long v;

	errno = 0;
	v = strtol(s, &end, 10);
	if (errno || end == s || *end != '\0' || v < lo || v > hi) {
		errno = EINVAL;
		return -1;
	}
	*out = v;
	return 0;
}

int hb_init(struct hb *hb)
{
	const char *fd_s = getenv(HB_FD_ENV), *pid_s = getenv(HB_SUPER_PID_ENV);
	long fd, pid;

	memset(hb, 0, sizeof(*hb));
	hb->fd = -1;
	if (!fd_s || !*fd_s)
		return 0;
	if (parse_long(fd_s, 0, 65535, &fd) < 0)
		return -1;
	/* Inherited without CLOEXEC on purpose; don't pass it any further. */
	if (fcntl((int)fd, F_SETFD, FD_CLOEXEC) < 0)
		return -1;
	if (prctl(PR_SET_PDEATHSIG, SIGTERM) < 0)
		return -1;
	/* If super died before the prctl, we were reparented and no signal comes. */
	if (pid_s && *pid_s) {
		if (parse_long(pid_s, 1, 0x7fffffff, &pid) < 0)
			return -1;
		if (getppid() != (pid_t)pid) {
			errno = ESRCH;
			return -1;
		}
	}
	hb->fd = (int)fd;
	return 1;
}

int hb_tick(struct hb *hb, int64_t now_ns)
{
	struct hb_msg m;
	ssize_t n;

	if (hb->fd < 0 || now_ns < hb->next_ns)
		return 0;
	memset(&m, 0, sizeof(m));
	m.type = MSG_HB;
	m.seq = hb->seq++;
	hb->next_ns = now_ns + HB_PERIOD_NS;
	n = send(hb->fd, &m, sizeof(m), MSG_NOSIGNAL | MSG_DONTWAIT);
	if (n == (ssize_t)sizeof(m))
		return 0;
	if (n < 0 && (errno == EAGAIN || errno == EWOULDBLOCK || errno == EINTR))
		return 0;
	if (n >= 0)
		errno = EMSGSIZE;
	return -1;
}

int hb_readable(struct hb *hb)
{
	char buf[16];
	ssize_t n;

	if (hb->fd < 0)
		return 0;
	n = recv(hb->fd, buf, sizeof(buf), MSG_DONTWAIT);
	if (n > 0)
		return 0;	/* super sends nothing today; ignore */
	if (n == 0) {
		errno = ENOTCONN;
		return -1;
	}
	if (errno == EAGAIN || errno == EWOULDBLOCK || errno == EINTR)
		return 0;
	return -1;
}

int64_t hb_due_ns(const struct hb *hb)
{
	return hb->fd < 0 ? INT64_MAX : hb->next_ns;
}

/* Per-child supervision state for dlby-super (DESIGN.md §2 E). Pure state: no
 * syscalls, time passed in, so the timing and exit-code rules are unit-tested.
 *
 *   hang:    no heartbeat within SUP_HB_FIRST_NS of start, or SUP_HB_SILENCE_NS
 *            of silence after one -> TERM; still alive SUP_KILL_GRACE_NS later -> KILL
 *   restart: backoff 100 ms doubling to 30 s, reset after 60 s healthy; never gives up
 *   exits:   0 = stopped on request, no restart; 78 EX_CONFIG = don't restart;
 *            69, 70, any other code or any signal = restart. An exit after a kill
 *            super itself started is always restarted.
 */
#ifndef DLBY_SUPERVISE_H
#define DLBY_SUPERVISE_H

#include <stdbool.h>
#include <stdint.h>

#define SUP_HB_FIRST_NS    (10LL * 1000000000LL)
#define SUP_HB_SILENCE_NS  (5LL * 1000000000LL)
#define SUP_KILL_GRACE_NS  (500LL * 1000000LL)
#define SUP_HEALTHY_NS     (60LL * 1000000000LL)
#define SUP_BACKOFF_MIN_MS 100
#define SUP_BACKOFF_MAX_MS 30000

enum child_state {
	CH_IDLE,		/* never started: start now */
	CH_RUNNING,
	CH_TERMINATING,		/* SIGTERM sent after a lost heartbeat */
	CH_KILLING,		/* SIGKILL sent */
	CH_WAIT_RESTART,
	CH_DISABLED,		/* exited 78 */
	CH_STOPPED,		/* exited 0 on its own */
};

enum sup_action {
	SUP_NONE,
	SUP_START,
	SUP_TERM,
	SUP_KILL,
};

enum sup_exit {
	SUP_EXIT_RESTART,
	SUP_EXIT_DISABLED,
	SUP_EXIT_STOPPED,
};

struct child_sm {
	enum child_state state;
	int64_t start_ns;
	int64_t last_hb_ns;
	int64_t kill_at_ns;
	int64_t restart_at_ns;
	bool    got_hb;
	bool    killed_by_us;
	int     backoff_ms;	/* delay for the next restart */
	int     delay_ms;	/* delay chosen for the pending restart */
};

void sup_init(struct child_sm *c);
void sup_on_start(struct child_sm *c, int64_t now_ns);

/* Returns true for the first heartbeat since start. */
bool sup_on_hb(struct child_sm *c, int64_t now_ns);

/* status is a waitpid() status. */
enum sup_exit sup_on_exit(struct child_sm *c, int status, int64_t now_ns);

enum sup_action sup_tick(struct child_sm *c, int64_t now_ns);

/* Earliest time sup_tick() may return something other than SUP_NONE. */
int64_t sup_deadline(const struct child_sm *c);

#endif

#include "supervise.h"

#include <string.h>
#include <sys/wait.h>
#include <sysexits.h>

void sup_init(struct child_sm *c)
{
	memset(c, 0, sizeof(*c));
	c->state = CH_IDLE;
	c->backoff_ms = SUP_BACKOFF_MIN_MS;
}

void sup_on_start(struct child_sm *c, int64_t now_ns)
{
	c->state = CH_RUNNING;
	c->start_ns = now_ns;
	c->last_hb_ns = now_ns;
	c->got_hb = false;
	c->killed_by_us = false;
}

bool sup_on_hb(struct child_sm *c, int64_t now_ns)
{
	bool first = !c->got_hb;

	c->got_hb = true;
	c->last_hb_ns = now_ns;
	return first;
}

enum sup_exit sup_on_exit(struct child_sm *c, int status, int64_t now_ns)
{
	if (now_ns - c->start_ns >= SUP_HEALTHY_NS)
		c->backoff_ms = SUP_BACKOFF_MIN_MS;
	if (!c->killed_by_us && WIFEXITED(status)) {
		if (WEXITSTATUS(status) == 0) {
			c->state = CH_STOPPED;
			return SUP_EXIT_STOPPED;
		}
		if (WEXITSTATUS(status) == EX_CONFIG) {
			c->state = CH_DISABLED;
			return SUP_EXIT_DISABLED;
		}
	}
	c->delay_ms = c->backoff_ms;
	c->restart_at_ns = now_ns + (int64_t)c->backoff_ms * 1000000;
	c->backoff_ms = c->backoff_ms * 2 > SUP_BACKOFF_MAX_MS ? SUP_BACKOFF_MAX_MS : c->backoff_ms * 2;
	c->state = CH_WAIT_RESTART;
	return SUP_EXIT_RESTART;
}

static int64_t hb_deadline(const struct child_sm *c)
{
	return c->got_hb ? c->last_hb_ns + SUP_HB_SILENCE_NS : c->start_ns + SUP_HB_FIRST_NS;
}

enum sup_action sup_tick(struct child_sm *c, int64_t now_ns)
{
	switch (c->state) {
	case CH_IDLE:
		return SUP_START;
	case CH_WAIT_RESTART:
		return now_ns >= c->restart_at_ns ? SUP_START : SUP_NONE;
	case CH_RUNNING:
		if (now_ns <= hb_deadline(c))
			return SUP_NONE;
		c->state = CH_TERMINATING;
		c->killed_by_us = true;
		c->kill_at_ns = now_ns + SUP_KILL_GRACE_NS;
		return SUP_TERM;
	case CH_TERMINATING:
		if (now_ns < c->kill_at_ns)
			return SUP_NONE;
		c->state = CH_KILLING;
		return SUP_KILL;
	default:
		return SUP_NONE;
	}
}

int64_t sup_deadline(const struct child_sm *c)
{
	switch (c->state) {
	case CH_IDLE:
		return INT64_MIN;
	case CH_WAIT_RESTART:
		return c->restart_at_ns;
	case CH_RUNNING:
		return hb_deadline(c) + 1;
	case CH_TERMINATING:
		return c->kill_at_ns;
	default:
		return INT64_MAX;
	}
}

