static void close_keep_errno(int fd)
{
	int err = errno;

	(void)close(fd);	/* the fd is released even if close reports an error */
	errno = err;
}

static bool list_has(const char *list, const char *name)
{
	size_t len = strlen(name);
	const char *p = list, *comma;

	for (;;) {
		comma = strchr(p, ',');
		if ((size_t)(comma ? comma - p : (ptrdiff_t)strlen(p)) == len && strncmp(p, name, len) == 0)
			return true;
		if (!comma)
			return false;
		p = comma + 1;
	}
}

/* Every name in $DLBY_CHILDREN must be one of ours. */
static int check_list(const char *list)
{
	const char *p = list, *comma;
	size_t len, i;

	for (;;) {
		comma = strchr(p, ',');
		len = comma ? (size_t)(comma - p) : strlen(p);
		for (i = 0; i < MAX_CHILDREN; i++)
			if (strlen(all_children[i].name) == len && strncmp(p, all_children[i].name, len) == 0)
				break;
		if (i == MAX_CHILDREN) {
			log_msg(LOG_E, "bad_config %s=%s unknown=%.*s", CHILDREN_ENV, list, (int)len, p);
			return -1;
		}
		if (!comma)
			return 0;
		p = comma + 1;
	}
