		return -1;
	for (i = 0; i < MAX_CHILDREN; i++) {
		if (list && *list && !list_has(list, all_children[i].name))
			continue;
		c = &kids[nkids++];
		memset(c, 0, sizeof(*c));
		c->def = &all_children[i];
		c->pid = -1;
		c->hb_fd = -1;
		sup_init(&c->sm);
