	hub->store_pending++;
	hub->store_dropped++;
}

static void send_state(struct hub *hub, int64_t now)
{
	static const uint8_t to_fuse[] = {
		[H_BLIND] = ST_BLIND,
		[H_DEG]   = ST_DEG_CLEAR,
		[H_OK]    = ST_CLEAR,
	};
	struct alert_msg m;

	memset(&m, 0, sizeof(m));
	m.type = MSG_ALERT;
	m.state = to_fuse[health_state(&hub->h)];
	m.lost_mask = (uint8_t)((hub->h.up[SENSOR_RADAR] ? 0 : LOST_RADAR) |
