	CHECK(hb_readable(&hb) == 0);
	CHECK(close(sv[0]) == 0);
	CHECK(hb_readable(&hb) == -1);
	CHECK(hb_tick(&hb, 3 * SEC) == -1 && errno == EPIPE);
	CHECK(close(sv[1]) == 0);
}

